import axios from "axios";
import appsettings from "../../appsettings.json"
import { generateUUID, compressLZW, decompressLZW, compressBase64, decompressBase64 } from "../utilities/utils";
import {
  BrowserRouter as Router,
  Route,
  Routes,
  useNavigate,
  Link,
  Navigate
} from "react-router-dom";

const BASE_URL = process.env.REACT_APP_FinXCoreUrl;

const api = axios.create({
  baseURL: BASE_URL,
  withCredentials: true
});

// Initialize loading state
let setLoading;

export function initializeLoadingSetter(setter) {
  setLoading = setter;
}


function LoginRedirect() {

  const navigate = useNavigate();
  navigate("/Login");
  return null;
}

const triggerSessionExpiredEvent = () => {
  const event = new CustomEvent("sessionExpired");
  window.dispatchEvent(event);
};


const loginstatuscheck = async () => {

  try {

    const apiendpoints = appsettings.ApiEndpoints;

    const longinstatusurl = apiendpoints.LoginStatus

    const loginstatusresponse = await api.post(longinstatusurl);

    let strResponse = JSON.parse(decompressBase64(loginstatusresponse.data));


    if (!strResponse.body.IsValid) {
      //window.location.href = "/login"; // Redirect to login page
      triggerSessionExpiredEvent();
    }
  }
  catch (sessionError) {
    console.error("Session check failed:", sessionError);
   // window.location.href = "/login"; // Redirect if session check fails
   triggerSessionExpiredEvent();
  }

}

api.interceptors.response.use(
  (response) => {

    return response;
  },

  (error) => {
    debugger;
    if (error.response && error.response.status === 401) {

      loginstatuscheck();
    }
    return Promise.reject(error);
  }
);

export function PostCallHeader(url, data, header) {
  const respdata = axios.post(url, data, header);
  return respdata;
}

export default api;